"""
Master Interview Book — deep interview topics (P0_PROMPT.txt "JOB-FIRST
MASTER INTERVIEW BOOK V1"). This module is imported by build_learn_tree.py
(inside main(), to avoid a circular import) and is NOT a second knowledge
system: every topic built here becomes a normal node in the same canonical
agent/web/learn-tree.json that both the interactive Learn UI and the PDF
book generator read from.

Each deep topic uses the 17-part schema demanded by the task:
  why, history_evolution, why_now, big_picture, design_intellect,
  how_exactly, low_level_internals, who, industry, business, product,
  cost_economics, failure_incident, alternatives_tradeoffs, scenario,
  interview_mode, current_status_2026
plus a top-level `priority` (INTERVIEW_ESSENTIAL / IMPORTANT / MASTERY_DEPTH)
and the existing `experience_classification` field, extended here with two
new honest values:
  REAL_PROFESSIONAL_EXPERIENCE — only if resume/repo evidence genuinely
    supports the Creator having done this on the job. Not used anywhere in
    this module unless such evidence exists (see docs/EXPERIENCE_EVIDENCE.md);
    absent that file, this module never assigns it.
  STUDY_SCENARIO — a realistic, clearly-labeled hypothetical used for
    interview rehearsal. Never presented as real experience.
Existing values LEARNED_UNDERSTOOD / CURRENT_PROJECT_EXPERIENCE /
PLANNED_NOT_EXPERIENCED are reused unchanged for topics genuinely evidenced
by this repository's own code.
"""

import re

REAL_PROF = "REAL_PROFESSIONAL_EXPERIENCE"
STUDY = "STUDY_SCENARIO"
CURRENT = "CURRENT_PROJECT_EXPERIENCE"
LEARNED = "LEARNED_UNDERSTOOD"

ESSENTIAL = "INTERVIEW_ESSENTIAL"
IMPORTANT = "IMPORTANT"
MASTERY = "MASTERY_DEPTH"


def _slugify(text: str) -> str:
    s = re.sub(r"[^a-z0-9]+", "-", text.lower()).strip("-")
    return s or "topic"


def itopic(title, priority, classification, *, short_overview=None,
           why=None, history_evolution=None, why_now=None, big_picture=None,
           design_intellect=None, how_exactly=None, low_level_internals=None,
           who=None, industry=None, business=None, product=None,
           cost_economics=None, failure_incident=None,
           alternatives_tradeoffs=None, scenario=None, interview_mode=None,
           current_status_2026=None, evidence=None, related=None):
    sections = {
        "why": why,
        "history_evolution": history_evolution,
        "why_now": why_now,
        "big_picture": big_picture,
        "design_intellect": design_intellect,
        "how_exactly": how_exactly,
        "low_level_internals": low_level_internals,
        "who": who,
        "industry": industry,
        "business": business,
        "product": product,
        "cost_economics": cost_economics,
        "failure_incident": failure_incident,
        "alternatives_tradeoffs": alternatives_tradeoffs,
        "scenario": scenario,
        "interview_mode": interview_mode,
        "current_status_2026": current_status_2026,
    }
    if evidence:
        sections["evidence"] = evidence
    sections = {k: v for k, v in sections.items() if v not in (None, "", [], {})}
    node = {
        "slug": _slugify(title),
        "title": title,
        "kind": "topic",
        "short_overview": short_overview or (why[:220] if why else title),
        "experience_classification": classification,
        "priority": priority,
        "children": [],
        "sections": sections,
    }
    if related:
        node["related"] = related
    return node


def im(sec_15=None, sec_30=None, min_2=None, deep_technical=None,
       system_design=None, business_value=None, incident_debugging=None,
       followups=None):
    d = {
        "sec_15": sec_15, "sec_30": sec_30, "min_2": min_2,
        "deep_technical": deep_technical, "system_design": system_design,
        "business_value": business_value,
        "incident_debugging": incident_debugging,
    }
    d = {k: v for k, v in d.items() if v}
    if followups:
        d["followups"] = followups
    return d


