# Imported lazily by build_learn_tree.main() to avoid a circular import
# (this module needs leaf/branch/slugify, defined at build_learn_tree's
# module scope, before build_learn_tree can import this module back).
from build_learn_tree import leaf as _leaf, branch as _branch, PLANNED  # noqa: E402


def _rl(title, what, cls=LEARNED, how=None, related=None, evidence=None):
    """Reference-level leaf using the existing 4-value classification --
    broad-map coverage nodes are intentionally light (not full 17-section
    deep topics), so they reuse leaf()'s existing schema rather than
    itopic()'s. CURRENT is only ever used here when this project's own
    code genuinely demonstrates the concept; STUDY_SCENARIO/REAL_PROFESSIONAL
    are reserved for the full deep topics above, never asserted for a
    one-line reference leaf with no real backing evidence."""
    return _leaf(title, what, cls, how=how, related=related, evidence=evidence)


def build_java_core_domain(deep):
    children = [
        _rl("Objects & References", "A Java variable of object type holds a reference (a pointer-like handle) to heap memory, never the object's data directly — assignment copies the reference, not the object."),
        _rl("Immutability", "An object whose state cannot change after construction (e.g. String, records) — inherently thread-safe with no synchronization needed, and easier to reason about."),
        _rl("equals() & hashCode()", "Must be overridden together: two equal objects must have the same hashCode, or hash-based collections (HashMap/HashSet) silently break (an object 'disappears' because it's looked up in the wrong bucket)."),
        _rl("Collections Framework", "List/Set/Map and their standard implementations (ArrayList vs LinkedList, HashMap vs TreeMap) — chosen by real access-pattern trade-offs (index access vs. insertion, ordering, uniqueness)."),
        _rl("Generics", "Compile-time type safety for containers/APIs via type erasure — the compiler enforces types, but the runtime bytecode has type information erased, which explains generics' well-known runtime limitations (no `new T()`, no generic array creation)."),
        _rl("Exceptions: Checked vs Unchecked", "Checked exceptions force a caller to handle or declare them (compiler-enforced); unchecked (RuntimeException) don't — a real, debated API design trade-off, not just syntax."),
        _rl("Streams & Functional Interfaces", "Declarative, often-lazy data-processing pipelines (map/filter/reduce) over a Supplier/Function/Predicate/Consumer functional-interface foundation, popularized by Java 8 (2014)."),
        deep["java-concurrency-jmm"],
        _rl("Synchronization, volatile, Locks, Atomics", "The concrete toolbox for safe concurrent state: synchronized (mutual exclusion + visibility), volatile (visibility only), java.util.concurrent locks (more flexible than synchronized), atomics (lock-free single-variable updates)."),
        _rl("Executors & Thread Pools", "java.util.concurrent.ExecutorService manages a pool of reusable worker threads instead of creating a new OS thread per task — bounds resource usage and decouples task submission from execution."),
        _rl("CompletableFuture", "Composable asynchronous computation (then/combine/exceptionally chains) added in Java 8, letting async code avoid deeply nested callbacks ('callback hell')."),
        _rl("Virtual Threads (Project Loom)", "Java 21+ lightweight threads managed by the JVM rather than mapped 1:1 to OS threads, letting a thread-per-request programming model scale to huge concurrency without the old per-OS-thread memory/scheduling cost."),
        _rl("Thread Safety Design", "Designing a class to be safely usable by multiple threads by construction (immutability, confinement, or correct synchronization) rather than hoping callers synchronize correctly externally."),
    ]
    node = _branch("Java Core", "Core language, collections, and concurrency knowledge every Java backend interview assumes as baseline.", children)
    node["kind"] = "domain"
    return node


def build_jvm_domain(deep):
    children = [
        _rl("Source to Bytecode to Execution", "javac compiles .java source to .class bytecode (a portable, JVM-specific instruction set), which the JVM then interprets and/or JIT-compiles to native machine code at runtime.", CURRENT,
            how="This project's app/ module is compiled via Maven (mvnw) into real .class files run on a real JVM."),
        _rl("Class Loading", "The JVM loads a class's bytecode into memory lazily (on first real use), verifies it, and initializes its static state exactly once, via a delegation hierarchy of class loaders (bootstrap -> platform -> application)."),
        _rl("Interpreter vs JIT Compilation", "The JVM initially interprets bytecode (slow but instant-start), then profiles which methods run hottest and JIT-compiles just those to optimized native machine code (fast, but with warm-up delay) — a deliberate startup-latency vs. peak-throughput trade-off."),
        _rl("JVM Stack, Heap & Metaspace", "Each thread has its own stack (method frames, local variables, primitives); all threads share one heap (objects); Metaspace (off-heap since Java 8) holds class metadata."),
        deep["jvm-memory-gc"],
        _rl("OutOfMemoryError & Memory Leaks", "OOM is a symptom (the heap or Metaspace genuinely filled), not always a 'leak' in the C/C++ sense — in Java it almost always means objects are still reachable (referenced) longer than intended, not that memory was literally lost."),
        _rl("CPU / Thread Relationship & Context Switching", "The OS schedules threads onto a fixed number of CPU cores; more runnable threads than cores means the OS time-slices between them, and each switch has a real (if small) cost — a key reason unbounded thread creation degrades performance."),
        _rl("Profiling & Performance Diagnosis", "Tools (JFR/Java Flight Recorder, async-profiler, VisualVM, heap/thread dumps) that turn 'the app feels slow' into a specific, evidenced hot method, lock, or memory-retention path, rather than guessing."),
    ]
    node = _branch("JVM Internals", "What actually happens between writing Java source and a running, executing process — the mechanical layer most interview 'why is this slow/crashing' questions live in.", children)
    node["kind"] = "domain"
    return node


