def build_database_jpa_domain(deep):
    children = [
        deep["jdbc-hikaricp-pool-sizing"],
        _rl("SQL Execution Fundamentals", "How a SQL statement is parsed, planned, and executed by the database engine — the foundation the query-plan/index material builds on."),
        deep["indexes-query-execution"],
        deep["db-transactions-isolation"],
        _rl("Optimistic vs Pessimistic Locking", "Pessimistic locking (SELECT FOR UPDATE) blocks concurrent access up front; optimistic locking (a version column checked on write) allows concurrent reads and only fails at write time if a conflict occurred — different trade-offs for contention frequency."),
        _rl("Deadlocks", "Two transactions each holding a lock the other needs, waiting on each other forever — resolved by the database's own deadlock detector aborting one transaction, which the application must catch and retry."),
        deep["jpa-n-plus-one"],
        _rl("Fetch Strategies (Lazy vs Eager)", "Whether an association loads immediately with its parent or only on first access — the direct lever that creates or avoids the N+1 problem, chosen per use case rather than as one global mapping default."),
        _rl("Pagination", "Returning data in bounded pages (LIMIT/OFFSET or keyset/cursor-based) instead of a full result set — essential once a table's row count makes a full fetch slow or memory-unsafe; keyset pagination scales better than OFFSET at large page numbers."),
        _rl("Schema Migration", "Versioned, repeatable, reviewable database schema changes (Flyway/Liquibase) instead of manual, undocumented ALTER statements — critical once more than one environment/developer touches the same schema."),
        _rl("Database Constraints", "Database-enforced rules (NOT NULL, UNIQUE, FOREIGN KEY, CHECK) that guarantee data integrity even if application-level validation is ever bypassed or buggy — the last line of defense, not a redundant one."),
        _rl("Database Performance Diagnosis", "Slow-query logs, EXPLAIN ANALYZE, and connection-pool metrics are the standard toolkit for turning 'the database feels slow' into a specific, evidenced root cause."),
    ]
    node = _branch("Database / SQL / JPA", "How data is stored, queried, and kept consistent, from raw SQL execution up through JPA/Hibernate's object-relational mapping.", children)
    node["kind"] = "domain"
    return node


def build_rest_api_domain(deep):
    children = [
        _rl("HTTP Methods & Status Codes", "GET/POST/PUT/PATCH/DELETE's defined semantics (safe, idempotent, or neither) and status code families (2xx success, 4xx client error, 5xx server error) form the shared vocabulary any REST API is expected to honor.", CURRENT),
        _rl("Validation & Error Contracts", "A consistent, machine-readable error response shape (not just a status code) lets callers programmatically react to a failure rather than parsing a human-readable message string."),
        _rl("PUT vs PATCH", "PUT replaces a resource wholesale (idempotent by definition); PATCH applies a partial update (not inherently idempotent unless specifically designed to be) — a frequently-confused, frequently-interviewed distinction."),
        deep["rest-idempotency-deep"],
        _rl("API Versioning", "Evolving an API without breaking existing callers, via URL path, header, or strictly-additive-only changes — a real operational commitment, not a one-time decision."),
        _rl("Pagination & Filtering", "Query-parameter-driven pagination/filtering/sorting conventions that keep list endpoints usable and bounded as data volume grows."),
        _rl("API Authentication & Rate Limiting", "Verifying caller identity (API keys, OAuth2 tokens) and bounding how often a caller may call, to protect the API from abuse and ensure fair capacity sharing across clients."),
        _rl("Backward Compatibility", "A new API version/field addition must never break an existing, unmodified client — the guiding discipline behind additive-only changes and careful deprecation windows."),
    ]
    node = _branch("REST / API Design", "The contracts through which a frontend or another service communicates with a backend, and the conventions that keep those contracts stable over time.", children)
    node["kind"] = "domain"
    return node


def build_microservices_distributed_domain(deep):
    children = [
        deep["microservice-boundaries"],
        _rl("Modular Monolith vs Microservices", "A single deployable unit organized into clear internal modules (captures most maintainability benefits cheaply) versus true independently-deployed services (independent scaling/deployment, at real infrastructure/operational cost) — a deliberate choice, not a maturity ladder.", CURRENT,
            how="This project's own Customer app is a deliberate single-service (not microservices) architecture, matching its current team size and scale."),
        _rl("Sync vs Async Communication", "Call synchronously only when the caller genuinely needs an immediate answer; use asynchronous events for everything else, to avoid needlessly coupling availability/latency across service boundaries."),
        deep["distributed-consistency-saga-outbox"],
        _rl("Eventual Consistency", "Accepting that different parts of a distributed system may briefly disagree, converging to a consistent state over time — the natural consequence of choosing availability/decoupling over immediate cross-service consistency."),
        _rl("Idempotent Consumers", "A message/event consumer designed so processing the same message twice (an expected consequence of at-least-once delivery) produces the same effect as processing it once."),
        deep["resilience-retry-timeout-circuit-breaker"],
        _rl("Bulkhead Pattern", "Isolating a limited pool of resources (threads/connections) per-dependency so one dependency's exhaustion can't starve calls to unrelated, healthy dependencies — named after a ship's compartmentalized hull."),
        _rl("Backpressure", "A consumer signaling 'slow down' to a producer that's sending faster than it can process, rather than silently dropping work or unboundedly buffering until it runs out of memory."),
        _rl("Failure Isolation", "Designing so one component's failure is contained rather than cascading — the unifying goal timeout/retry/circuit-breaker/bulkhead all serve together."),
    ]
    node = _branch("Microservices / Distributed Systems", "Designing systems whose components run on separate machines/processes, communicate over an unreliable network, and must stay correct and available despite that.", children)
    node["kind"] = "domain"
    return node


def build_redis_caching_domain(deep):
    children = [
        _rl("Why Cache", "Caching trades a small amount of memory for a large reduction in latency/load for data that's read far more often than it changes and is expensive to produce."),
        deep["redis-caching-invalidation"],
        _rl("Eviction Policies", "When a cache reaches its memory limit, an eviction policy (LRU, LFU, or none/error-on-full) decides what to remove — chosen based on the actual access-pattern shape of the cached data."),
        _rl("Stale Data & Staleness Tolerance", "Every cache is a bet that slightly-out-of-date data is an acceptable trade for speed — the acceptable staleness window must be an explicit, stated requirement, not an accidental byproduct of whatever TTL was easiest to type."),
        _rl("Distributed Cache Consistency", "When multiple application instances share one cache (or each has its own local cache), a write from one instance must be visible (or invalidated) consistently for every instance, not just the one that made the write."),
        _rl("When NOT to Cache", "Data that changes as often as it's read, data where staleness is genuinely unacceptable (e.g. an exact financial balance), or data that's already cheap to fetch, are all cases where caching adds invalidation complexity for little or no real benefit."),
    ]
    node = _branch("Redis / Caching", "Storing a cheap-to-read copy of expensive-to-produce data, and the specific ways that convenience creates correctness risk if not deliberately managed.", children)
    node["kind"] = "domain"
    return node


def build_kafka_domain(deep):
    children = [
        _rl("Why Messaging / Event-Driven", "Decoupling a producer from its consumers in time and in knowledge of each other — the producer doesn't need to know who's listening, or whether they're currently available."),
        _rl("Broker, Topic & Partition", "A broker stores topics; a topic is split into partitions for parallelism, each an independent, ordered, append-only log."),
        _rl("Consumer Groups & Offsets", "Each consumer group tracks its own independent read position (offset) per partition, letting multiple different applications each read the full event stream at their own pace without interfering."),
        _rl("Ordering Guarantees", "Events are ordered only within a single partition, never across partitions — a deliberate trade for horizontal scalability that every consumer design must account for explicitly."),
        deep["kafka-delivery-semantics"],
        _rl("Dead Letter Queues (DLQ)", "A separate destination for messages that repeatedly fail processing, so one poison-pill message can't block an entire partition's progress forever, and failures remain visible for investigation rather than silently retried indefinitely."),
        _rl("Schema Evolution", "Event schemas change over time; a schema registry with compatibility rules (backward/forward compatible changes only) prevents a producer's update from breaking existing consumers still expecting the old shape."),
        _rl("Consumer Lag & Backpressure", "Lag (how far behind a consumer group is from the latest produced offset) is the key health metric for an event-driven pipeline — growing lag signals a consumer that can't keep up and needs scaling or backpressure."),
        _rl("API vs Event: When to Choose Which", "A synchronous API call is right when the caller needs an immediate answer; an event is right when the caller doesn't need to wait and multiple independent parties may want to react — conflating the two is a common architecture mistake."),
    ]
    node = _branch("Kafka / Event-Driven Architecture", "Using a distributed, partitioned, replicated log as a high-throughput backbone for decoupled, multi-consumer event streaming.", children)
    node["kind"] = "domain"
    return node


